(() => {
  const O = window.__OURO__;
  O.gotoScene('menu', {});
  const m = O.scene('menu');
  const texts = O.texts('menu');
  const containers = m.children.list.filter((c) => c && c.type === 'Container');
  let rects = 0;
  let images = 0;
  containers.forEach((c) => {
    c.list.forEach((child) => {
      if (child && child.type === 'Rectangle') { rects += 1; }
      if (child && child.type === 'Image') { images += 1; }
    });
  });
  window.__T__ = {
    sceneKey: O.sceneKey(),
    containers: containers.length,
    rects: rects,
    images: images,
    hasP1: texts.some((x) => x.text === 'Player 1'),
    hasP2: texts.some((x) => x.text === 'Player 2'),
    chooseLabels: texts.filter((x) => x.text === 'Choose Colour:').length,
    controlsLabels: texts.filter((x) => x.text === 'Controls').length,
    hasInstructionsHeader: texts.some((x) => x.text === 'Game Instructions'),
    hasInstructionLine: texts.some((x) => x.text.indexOf('Player score +1') > -1),
    hasPrompt: texts.some((x) => x.text === 'hit [enter]'),
    audioLabel: m.audioText ? m.audioText.text : '',
    colorCount: m.colors.length,
    colors: m.colors.join('|'),
    p1Index: m.player1ColorIndex,
    p2Index: m.player2ColorIndex,
    boxSize: m.colorBoxSize,
    boxSpacing: m.colorBoxSpacing,
    hasCursor1: !!m.cursor1,
    hasCursor2: !!m.cursor2
  };
