})()

(() => {
  const O = window.__OURO__;
  O.gotoScene('game', { color1: '#DF1A2D', color2: '#0798BB' });
  const s = O.makeSnake(10, 10, {});
  const r = { made: !!s };
  r.len0 = s.body.getLength();
  r.headX = s.head.x;
  r.headY = s.head.y;
  r.direction0 = s.direction;
  r.nextDirection0 = s.nextDirection;
  r.size = s.size;
  r.movesPerSecond = s.movesPerSecond;
  r.color = s.color;
  r.grew = s.grow(2);
  r.len1 = s.body.getLength();
  const kids = s.body.getChildren();
  r.growAtTail = (kids[2].x === s.tail.x) && (kids[2].y === s.tail.y);
  r.stranded = s.handleOverlapSelf();
  r.wrapLeft = s.wrapHorizontalPosition(-1);
  r.wrapBottom = s.wrapVerticalPosition(35);
  r.moved = s.move(0);
  r.len2 = s.body.getLength();
  r.headAfterMoveY = s.headPosition.y;
  r.nextUpdatePositive = s.nextUpdateTime > 0;
  window.__T__ = r;
  return true;
})()

