(() => {
  const O = window.__OURO__;
  O.gotoScene('game', { color1: '#DF1A2D', color2: '#0798BB' });
  const s = O.makeSnake(10, 10, {});
  const r = { made: !!s };
  // The turn guards read the committed direction, so each case pins direction and
  // nextDirection explicitly. That keeps this checkpoint exclusive to the up/down
  // guard and independent of whether the direction commit itself works.
  s.direction = 'LEFT'; s.nextDirection = 'LEFT'; s.goUp();
  r.leftGoUp = s.nextDirection;
  s.direction = 'DOWN'; s.nextDirection = 'DOWN'; s.goUp();
  r.downGoUp = s.nextDirection;
  s.direction = 'RIGHT'; s.nextDirection = 'RIGHT'; s.goDown();
  r.rightGoDown = s.nextDirection;
  s.direction = 'UP'; s.nextDirection = 'UP'; s.goDown();
  r.upGoDown = s.nextDirection;
  s.direction = 'DOWN'; s.nextDirection = 'DOWN'; s.goLeft();
  r.downGoLeft = s.nextDirection;
  s.direction = 'LEFT'; s.nextDirection = 'LEFT'; s.goRight();
  r.leftGoRight = s.nextDirection;
  window.__T__ = r;
  return true;
})()

(() => {
  const O = window.__OURO__;
  O.gotoScene('game', { color1: '#DF1A2D', color2: '#0798BB' });
  const s = O.makeSnake(10, 10, {});
  const r = { direction0: s.direction, nextDirection0: s.nextDirection };
  s.goLeft();
  r.nextAfterGoLeft = s.nextDirection;
  s.move(0);
  r.directionAfterFirstStep = s.direction;
  // With the turn committed, a second left request and a right request must BOTH be
  // refused (the snake is now travelling left, so neither is perpendicular).
  s.goLeft();
  s.goRight();
  r.nextAfterRejectedTurns = s.nextDirection;
  s.move(100);
  r.directionAfterSecondStep = s.direction;
  window.__T__ = r;
  return true;
})()

