  r.sameColumnOnly = s.overlapsWith({ x: hx, y: hy + 160 });
  r.neitherAxis = s.overlapsWith({ x: hx + 160, y: hy + 160 });
  r.missingItem = s.overlapsWith(null);
  r.undefinedItem = s.overlapsWith(undefined);
  window.__T__ = r;
  return true;
})()

